function GardenSoilMoistureMeterMaker.init() GardenSoilMoistureMeterMaker.ironStock=14; GardenSoilMoistureMeterMaker.bronzeStock=12; GardenSoilMoistureMeterMaker.woodStock=12; GardenSoilMoistureMeterMaker.leatherStock=8; GardenSoilMoistureMeterMaker.silverStock=8; GardenSoilMoistureMeterMaker.goldStock=6; GardenSoilMoistureMeterMaker.jewelStock=4; GardenSoilMoistureMeterMaker.pearlStock=4; GardenSoilMoistureMeterMaker.productStock={}; GardenSoilMoistureMeterMaker.buildings={}; GardenSoilMoistureMeterMaker.maker=nil; GardenSoilMoistureMeterMaker.activeMaking={}; GardenSoilMoistureMeterMaker.totalProducts=0; GardenSoilMoistureMeterMaker.dayTimer=0; print("[GardenSoilMoistureMeterMaker] Royal Garden Soil Moisture Meter Maker System initialized (6 products, 4 buildings)") end
function GardenSoilMoistureMeterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenSoilMoistureMeterMaker.maker={name=n or ("Merilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilnik najet: %s (spretnost: %d)",GardenSoilMoistureMeterMaker.maker.name,s),"success") end; return true end
function GardenSoilMoistureMeterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenSoilMoistureMeterMaker.build(id) local ok,e=GardenSoilMoistureMeterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenSoilMoistureMeterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenSoilMoistureMeterMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenSoilMoistureMeterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenSoilMoistureMeterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenSoilMoistureMeterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenSoilMoistureMeterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenSoilMoistureMeterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenSoilMoistureMeterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenSoilMoistureMeterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenSoilMoistureMeterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenSoilMoistureMeterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenSoilMoistureMeterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenSoilMoistureMeterMaker.buildings==0 then return false,"Potrebna merilna delavnica" end; if not GardenSoilMoistureMeterMaker.maker then return false,"Potreben merilnik" end; return true end
function GardenSoilMoistureMeterMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenSoilMoistureMeterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenSoilMoistureMeterMaker.ironStock=GardenSoilMoistureMeterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenSoilMoistureMeterMaker.bronzeStock=GardenSoilMoistureMeterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenSoilMoistureMeterMaker.woodStock=GardenSoilMoistureMeterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenSoilMoistureMeterMaker.leatherStock=GardenSoilMoistureMeterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenSoilMoistureMeterMaker.silverStock=GardenSoilMoistureMeterMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenSoilMoistureMeterMaker.goldStock=GardenSoilMoistureMeterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenSoilMoistureMeterMaker.jewelStock=GardenSoilMoistureMeterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenSoilMoistureMeterMaker.pearlStock=GardenSoilMoistureMeterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenSoilMoistureMeterMaker.maker then t=math.max(1,t-math.floor(GardenSoilMoistureMeterMaker.maker.skill/13)) end; table.insert(GardenSoilMoistureMeterMaker.activeMaking,{id="gardensoilmoisturemeter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenSoilMoistureMeterMaker.completeMaking(m) local q=1.0+(GardenSoilMoistureMeterMaker.getQualityBonus()/100); if GardenSoilMoistureMeterMaker.maker then q=q+(GardenSoilMoistureMeterMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSoilMoistureMeterMaker.productStock[m.productType]=(GardenSoilMoistureMeterMaker.productStock[m.productType] or 0)+m.quantity; GardenSoilMoistureMeterMaker.totalProducts=GardenSoilMoistureMeterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSoilMoistureMeterMaker.maker then GardenSoilMoistureMeterMaker.maker.itemsMade=GardenSoilMoistureMeterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSoilMoistureMeterMaker.maker.skill=math.min(100,GardenSoilMoistureMeterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardensoilmoisturemeter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenSoilMoistureMeterMaker.update(dt) if not _G.state then return end; GardenSoilMoistureMeterMaker.dayTimer=GardenSoilMoistureMeterMaker.dayTimer+dt; if GardenSoilMoistureMeterMaker.dayTimer>=30 then GardenSoilMoistureMeterMaker.dayTimer=0; for i=#GardenSoilMoistureMeterMaker.activeMaking,1,-1 do local m=GardenSoilMoistureMeterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenSoilMoistureMeterMaker.completeMaking(m); table.remove(GardenSoilMoistureMeterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenSoilMoistureMeterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenSoilMoistureMeterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
